package org.sleepmonitor.app;
import android.app.*;import android.os.*;import android.content.*;import android.bluetooth.*;import android.bluetooth.le.*;import java.util.*;import java.io.*;import java.text.*;
public class MonitorService extends Service {
 public static volatile String status="Bereit"; public static volatile int oxygen=-1,pulse=-1,battery=-1; public static volatile long last=0; public static volatile boolean running=false; public static volatile long started=0, received=0, saved=0, lastSaved=0, disconnects=0; public static volatile String storage="Bereit"; FileOutputStream stream; File recordFile; long lastSync=0, connecting=0; BluetoothDevice device; public static final ArrayList<Integer> history=new ArrayList<>();
 final Handler h=new Handler(Looper.getMainLooper()); BluetoothGatt g; BluetoothLeScanner scanner; BluetoothGattCharacteristic writer; boolean scanning=false,ready=false; PowerManager.WakeLock lock; PrintWriter out; ByteArrayOutputStream buf=new ByteArrayOutputStream(); long sent=0;
 static final UUID S=UUID.fromString("14839ac4-7d7e-415c-9a42-167340cf2339"), W=UUID.fromString("8b00ace7-eb0b-49b0-bbe9-9aee0a26e1a3"), N=UUID.fromString("0734594a-a8e7-4b1a-a6b1-cd5243059a57"), D=UUID.fromString("00002902-0000-1000-8000-00805f9b34fb");
 byte[] cmd={(byte)0xaa,0x17,(byte)0xe8,0,0,0,0,0x1b};
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int f,int id){if(running)return START_NOT_STICKY; running=true; started=SystemClock.elapsedRealtime(); received=saved=lastSaved=disconnects=0; last=0; storage="Bereit"; NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("record","Messaufzeichnung",NotificationManager.IMPORTANCE_LOW));startForeground(1,new Notification.Builder(this,"record").setContentTitle("SleepMonitor").setContentText("Bluetooth-Aufzeichnung aktiv").setSmallIcon(android.R.drawable.ic_menu_recent_history).setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build());try{lock=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"SleepMonitor:record");lock.acquire(13*3600000L);File dir=new File(getFilesDir(),"records");dir.mkdirs();recordFile=new File(dir,"sleep-"+new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss-SSS",Locale.US).format(new Date())+".csv"); stream=new FileOutputStream(recordFile,true); out=new PrintWriter(new OutputStreamWriter(stream,java.nio.charset.StandardCharsets.UTF_8));out.println("timestamp_epoch_ms,spo2,pulse,battery,status,raw_hex");out.flush();if(out.checkError())throw new IOException("header"); storage="OK";}catch(Exception e){storage="Speicherfehler";status="Speicherfehler";stopSelf();return START_NOT_STICKY;} synchronized(history){history.clear();} scan();h.post(tick);return START_NOT_STICKY;}
 void scan(){if(!running)return;try{BluetoothAdapter a=getSystemService(BluetoothManager.class).getAdapter();scanner=a.getBluetoothLeScanner();if(scanner==null){status="Bluetooth einschalten";h.postDelayed(this::scan,5000);return;}status="Suche Band-WU";scanning=true;scanner.startScan(Collections.singletonList(new ScanFilter.Builder().setDeviceName("Band-WU 4721").build()),new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),cb);h.postDelayed(()->{if(scanning){stopScan();scan();}},15000);}catch(Exception e){status="Bluetooth: "+e.getClass().getSimpleName();h.postDelayed(this::scan,5000);}}
 void stopScan(){if(scanning){scanning=false;try{scanner.stopScan(cb);}catch(Exception ignored){}}}
 final ScanCallback cb=new ScanCallback(){public void onScanResult(int t,ScanResult r){h.post(()->{if(!scanning||!running)return;String n=r.getScanRecord()==null?null:r.getScanRecord().getDeviceName();if(n==null)n=r.getDevice().getName();if(n!=null&&n.startsWith("Band-WU")){stopScan();status="Verbinde "+n;device=r.getDevice();connecting=SystemClock.elapsedRealtime();g=device.connectGatt(MonitorService.this,false,gc,BluetoothDevice.TRANSPORT_LE);}});}};
 void reset(){disconnects++; android.util.Log.w("SleepMonitor","BLE reset: "+status); connecting=0;sent=0;ready=false;writer=null;buf.reset();oxygen=pulse=battery=-1;last=0;if(g!=null){try{g.close();}catch(Exception ignored){}g=null;}if(running)h.postDelayed(()->{if(!running||g!=null)return;try{if(device!=null){connecting=SystemClock.elapsedRealtime();g=device.connectGatt(this,false,gc,BluetoothDevice.TRANSPORT_LE);if(g!=null)return;}}catch(Exception e){android.util.Log.w("SleepMonitor","Reconnect",e);}scan();},3000);}
 final BluetoothGattCallback gc=new BluetoothGattCallback(){public void onConnectionStateChange(BluetoothGatt x,int s,int state){h.post(()->{if(x!=g)return;if(s==0&&state==BluetoothProfile.STATE_CONNECTED){status="Dienste lesen";x.discoverServices();}else reset();});}public void onServicesDiscovered(BluetoothGatt x,int s){h.post(()->{if(x!=g)return;BluetoothGattService svc=x.getService(S);if(s!=0||svc==null){reset();return;}writer=svc.getCharacteristic(W);BluetoothGattCharacteristic n=svc.getCharacteristic(N);if(writer==null||n==null||!x.setCharacteristicNotification(n,true)){reset();return;}BluetoothGattDescriptor d=n.getDescriptor(D);if(d==null){reset();return;}d.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);if(!x.writeDescriptor(d))reset();});}public void onDescriptorWrite(BluetoothGatt x,BluetoothGattDescriptor d,int s){h.post(()->{if(x!=g)return;if(s==0){ready=true;connecting=0;status="Verbunden";sent=0;}else reset();});}public void onCharacteristicChanged(BluetoothGatt x,BluetoothGattCharacteristic c){byte[] b=c.getValue().clone();h.post(()->{if(x==g&&c.getUuid().equals(N))receive(b);});}};
 final Runnable tick=new Runnable(){public void run(){if(!running)return;long now=System.currentTimeMillis();if(connecting!=0&&SystemClock.elapsedRealtime()-connecting>20000){status="Verbindungszeitlimit";device=null;reset();}if(ready&&g!=null){if(sent!=0&&now-sent>5000){status="Keine Antwort";reset();}else if(sent==0){buf.reset();writer.setWriteType(BluetoothGattCharacteristic.WRITE_TYPE_NO_RESPONSE);writer.setValue(cmd);if(g.writeCharacteristic(writer))sent=now;}}if(out!=null&&(last==0||now-last>2500)){save(now+",,,,missing,");}h.postDelayed(this,1000);}};
 void receive(byte[] b){if(sent==0)return;buf.write(b,0,b.length);if(buf.size()<21)return;byte[] p=buf.toByteArray();buf.reset();sent=0;int crc=0;for(int i=0;i<20;i++){crc^=p[i]&255;for(int j=0;j<8;j++)crc=((crc<<1)^((crc&128)!=0?7:0))&255;}StringBuilder raw=new StringBuilder();for(byte v:p)raw.append(String.format(Locale.US,"%02X",v&255));long now=System.currentTimeMillis();boolean valid=p.length==21&&(p[0]&255)==85&&p[5]==13&&crc==(p[20]&255);int o=p[7]&255,hr=(p[8]&255)|((p[9]&255)<<8),ba=p[14]&255;valid=valid&&o>0&&o<=100&&hr>0&&hr<=300; if(valid){oxygen=o;pulse=hr;battery=ba<=100?ba:-1;last=now;status="Verbunden";synchronized(history){history.add(o);if(history.size()>300)history.remove(0);}}else{oxygen=pulse=-1;status="Ungültiges Paket";}received++;save(now+","+(valid?o+","+hr+","+battery+",ok":",,,invalid")+","+raw);}
 void save(String row){if(out==null)return;try{out.println(row);out.flush();if(out.checkError())throw new IOException("CSV write");long t=SystemClock.elapsedRealtime();if(t-lastSync>=30000){stream.getFD().sync();lastSync=t;}saved++;lastSaved=System.currentTimeMillis();storage="OK";}catch(Exception e){storage="Speicherfehler: "+e.getClass().getSimpleName();android.util.Log.e("SleepMonitor",storage,e);try{out.close();stream=new FileOutputStream(recordFile,true);out=new PrintWriter(new OutputStreamWriter(stream,java.nio.charset.StandardCharsets.UTF_8));}catch(Exception reopen){android.util.Log.e("SleepMonitor","CSV reopen",reopen);}}}
 public void onDestroy(){running=false;h.removeCallbacksAndMessages(null);stopScan();if(g!=null)g.close();if(out!=null){out.flush();try{stream.getFD().sync();}catch(Exception e){storage="Speicherfehler beim Stoppen";}out.close();}if(lock!=null&&lock.isHeld())lock.release();status="Gestoppt";super.onDestroy();}
}